import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_rig_sandhya/core/models/component.dart';

void main() {
  group('Data Layer - Kannada Content Sanitization', () {
    test('madhyahnika_upasthana content has not been accidentally modified', () {
      final file = File('assets/i18n/kn/components/madhyahnika_upasthana.json');
      final component = Component.fromJson(jsonDecode(file.readAsStringSync()));
      expect(component.blocks.length, 18);
      expect(component.blocks[0].type, 'heading');
      expect(component.blocks[0].text, 'ಉಪಸ್ಥಾನ');
      expect(component.blocks[1].type, 'instruction');
      expect(component.blocks[1].text, 'ಪೂರ್ವಾಭಿಮುಖವಾಗಿ ನಿ೦ತು');
      expect(component.blocks[2].type, 'verse_sankalpa');
      expect(component.blocks[2].text, 'ಉದುತ್ಯ೦ ಜಾತವೇದಸಮಿತಿ ತ್ರಯೋದಶರ್ಚಸ್ಯ ಸೂಕ್ತಸ್ಯ\nಕಣ್ವ ಪುತ್ರಃ ಪ್ರಸ್ಕಣ್ವ ಋಷಿಃ ಸೂರ್ಯೋ ದೇವತಾ\nನವಾದ್ಯಾ ಗಾಯತ್ರೀ ಛ೦ದಃ ಚತಸ್ರೋಽನುಷ್ಟುಭಃ ಉದ್ವಯ೦ ತಮಸಸ್ಪರೀತಿ\nಉದ್ದ್ಯನ್ನದ್ಯೇತ್ಯಯ೦ ತೃಚಃ ರೋಗಘ್ನ ಉಪನಿಷದ೦ತ್ಯೋ ಅರ್ಧರ್ಚಷಃ ದ್ವಿಷನ್ನಾಶಿನೀ\nಸೂರ್ಯೋಪಸ್ಥಾನೇ ವಿನಿಯೋಗಃ ।');
      expect(component.blocks[3].type, 'verse_viniyoga');
      expect(component.blocks[3].text, 'ಓ೦ ಉದು॒ತ್ಯ೦ ಜಾ॒ತವೇ᳚ದಸ೦ ದೇ॒ವ೦ ವ॑ಹನ್ತಿ ಕೇ॒ತವಃ॑ । ದೃ॒ಶೇ ವಿಶ್ವಾ᳚ಯ॒ ಸೂರ್ಯಮ್᳚॥\nಅಪ॒ ತ್ಯೇ ತಾ॒ಯವೋ᳚ ಯಥಾ॒ ನಕ್ಷ॑ತ್ರಾಯನ್ತ್ಯ॒ಕ್ತುಭಿಃ॑। ಸೂರಾ᳚ಯ ವಿ॒ಶ್ವ ಚ॑ಕ್ಷಸೇ॥\nಅದೃ॑ಶ್ರಮಸ್ಯಕೇ॒ತವೋ॒ ವಿ ರ॒ಶ್ಮಯೋ॒ ಜನಾ॒ँ ಅನು॑ । ಭ್ರಾಜ᳚ನ್ತೋ ಅ॒ಗ್ನಯೋ᳚ ಯಥಾ॥\nತ॒ರಣಿ᳚ರ್ವಿ॒ಶ್ವದ॑ರ್ಶತೋ ಜ್ಯೋತಿ॒ಷ್ಕೃದ॑ಸಿ ಸೂರ್ಯ। ವಿಶ್ವ॒ಮಾಭಾ᳚ಸಿ ರೋಚ॒ನಮ್॥\nಪ್ರ॒ತ್ಯಙದೇ॒ವಾನಾ॒೦ ವಿಶಃ॑ ಪ್ರ॒ತ್ಯಙ್ಙುದೇ᳚ಷಿ॒ಮಾನು॑ಷಾನ್ । ಪ್ರ॒ತ್ಯಙ್ವಿಶ್ವ॒೦ ಸ್ವ॑ರ್ದೃ॒ಶೇ॥\nಯೇನಾ᳚ ಪಾವಕ॒ ಚಕ್ಷ॑ಸಾ ಭುರ॒ಣ್ಯ೦ತ॒೦ ಜನಾ॒ँ ಅನು॑ । ತ್ವ೦ ವ॑ರುಣ॒ ಪಶ್ಯ॑ಸಿ॥\nವಿದ್ಯಾಮೇ᳚ಷಿ॒ ರಜ॑ಸ್ಪೃ॒ಥ್ವಹಾ॒ ಮಿಮಾ᳚ನೋ ಅ॒ಕ್ತುಭಿಃ॑ । ಪಶ್ಯ॒ಞ್ಜನ್ಮಾ᳚ನಿ ಸೂರ್ಯ॥\nಸ॒ಪ್ತ ತ್ವಾ᳚ ಹ॒ರಿತೋ॒ ರಥೇ॒ ವಹ᳚ನ್ತಿ ದೇವ ಸೂರ್ಯ । ಶೋ॒ಚಿಷ್ಕೇ᳚ಶ೦ ವಿಚಕ್ಷಣ ॥\nಅಯು॑ಕ್ತ ಸ॒ಪ್ತಶು॒ನ್ಧ್ಯುವಃ॒ ಸೂರೋ॒ರಥ॑ಸ್ಯ ನ॒ಪ್ತ್ಯಃ॑ । ತಾಭಿ᳚ರ್ಯಾತಿ॒ ಸ್ವಯು॑ಕ್ತಿಭಿಃ ॥\nಉದ್ವ॒ಯ೦ತಮ॑ಸ॒ಸ್ಪರಿ॒ ಜ್ಯೋತಿ॒ಷ್ಪಶ್ಯ᳚೦ತ॒ ಉತ್ತ॑ರಮ್ । ದೇ॒ವ೦ ದೇ᳚ವ॒ತ್ರಾ ಸೂರ್ಯ॒ಮಗ᳚ನ್ಮ॒ ಜ್ಯೋತಿ॑ರುತ್ತ॒ಮಮ್ ॥\nಉ॒ದ್ಯನ್ನ॒ದ್ಯ ಮಿ॑ತ್ರಮಹ ಆ॒ರೋಹ॒ನ್ನುತ್ತ॑ರಾ॒೦ ದಿವಮ್᳚ । ಹೃ॒ದ್ರೋ॒ಗ೦ ಮಮ॑ ಸೂರ್ಯ ಹರಿ॒ಮಾಣ᳚೦ ಚ ನಾಶಯ ॥\nಶುಕೇ᳚ಷು ಮೇ ಹರಿ॒ಮಾಣ᳚೦ ರೋಪ॒ಣಾಕಾ᳚ಸು ದಧ್ಮಸಿ । ಅಥೋ᳚ ಹಾರಿದ್ರ॒ವೇಷು॑ ಮೇ ಹರಿ॒ಮಾಣ॒೦ ನಿ ದ॑ಧ್ಮಸಿ ॥\nಉದ॑ಗಾದ॒ಯಮಾ᳚ದಿತ್ಯೋ ವಿಶ್ವೇ᳚ ನ॒ ಸಹ॑ಸಾ ಸ॒ಹ । ದ್ವಿ॒ಷ೦ತ॒೦ ಮಹ್ಯ᳚೦ ರ॒ನ್ಧಯ॒ನ್ಮೋ ಅ॒ಹ೦ ದ್ವಿ॑ಷ॒ತೇ ರ॑ಧಮ್॥');
      expect(component.blocks[4].type, 'verse_sankalpa');
      expect(component.blocks[4].text, 'ಚಿತ್ರ೦ ದೇವಾನಾ೦ ಇತಿ ಷಡರ್ಚಸ್ಯ ಸೂಕ್ತಸ್ಯ ಆ೦ಗೀರಸಃ ಪುತ್ರ ಕುತ್ಸ ಋಷಿಃ ಸೂರ್ಯೋ ದೇವತಾ ತ್ರಿಷ್ಟುಪ್ ಛ೦ದಃ\nಸೂರ್ಯೋಪಸ್ಥಾನೇ ವಿನಿಯೋಗಃ ।');
      expect(component.blocks[5].type, 'verse_viniyoga');
      expect(component.blocks[5].text, 'ಚಿ॒ತ್ರ೦ದೇ॒ವಾನಾ॒ಮುದ॑ಗಾ॒ದನೀ᳚ಕ॒೦ ಚಕ್ಷು᳚ರ್ಮಿ॒ತ್ರಸ್ಯ॒ ವರು॑ಣಸ್ಯಾ॒ಗ್ನೇಃ ।\nಆಪ್ರಾ॒ದ್ಯಾವಾ᳚ಪೃಥಿ॒ವೀ ಅ॒೦ತರಿ॑ಕ್ಷ॒೦ ಸೂರ್ಯ॑ ಆ॒ತ್ಮಾ ಜಗ॑ತಸ್ತ॒ಸ್ಥುಷ॑ಶ್ಚ ॥\nಸೂರ್ಯೋ᳚ ದೇ॒ವೀಮು॒ಶಸ॒೦ ರೋಚ॑ಮಾನಾ॒೦ ಮರ್ಯೋ॒ ನ ಯೋಷಾ᳚ಮ॒ಭ್ಯೇ᳚ತಿ ಪ॒ಶ್ಚಾತ್ ।\nಯತ್ರಾ॒ ನರೋ᳚ ದೇವ॒ಯ೦ತೋ᳚ ಯು॒ಗಾನಿ॑ ವಿತನ್ವ॒ತೇ ಪ್ರತಿ॑ ಭ॒ದ್ರಾಯ॑ ಭ॒ದ್ರಮ್ ॥\nಭ॒ದ್ರಾ ಅಶ್ವಾ᳚ ಹ॒ರಿತಃ॒ ಸೂರ್ಯ॑ಸ್ಯ ಚಿ॒ತ್ರಾ ಏತ॑ಗ್ವಾ ಅನು॒ಮಾದ್ಯಾ᳚ಸಃ ।\nನ॒ಮ॒ಸ್ಯ೦ತೋ᳚ ದಿ॒ವ ಆ ಪೃ॒ಷ್ಠಮ॑ಸ್ಥುಃ॒ ಪರಿ॒ ದ್ಯಾವಾ᳚ಪೃಥಿ॒ವೀ ಯ᳚೦ತಿ ಸ॒ದ್ಯಃ ॥\nತತ್ಸೂರ್ಯ॑ಸ್ಯ ದೇವ॒ತ್ವ೦ ತನ್ಮ॑ಹಿ॒ತ್ವ೦ ಮ॒ಧ್ಯಾ ಕರ್ತೋ॒ರ್ವಿತ॑ತ॒೦ ಸ೦ಜ॑ಭಾರ ।\nಯ॒ದೇದಯು॑ಕ್ತ ಹ॒ರಿತಃ॑ ಸ॒ದಸ್ಥಾ॒ದಾದ್ರಾತ್ರೀ॒ ವಾಸ॑ಸ್ತನುತೇಸಿ॒ಮಸ್ಮೈ᳚ ॥\nತನ್ಮಿ॒ತ್ರಸ್ಯ॒ ವರು॑ಣಸ್ಯಾಭಿ॒ಚಕ್ಷೇ॒ ಸೂರ್ಯೋ᳚ ರೂ॒ಪ೦ ಕೃ॑ಣುತೇ॒ದ್ಯೋರು॒ಪಸ್ಥೇ᳚ ।\nಅ॒ನ॒೦ತಮ॒ನ್ಯದ್ರುಶ॑ದಸ್ಯ॒ ಪಾಜಃ॑ ಕೃ॒ಷ್ಣಮ॒ನ್ಯದ್ಧ॒ರಿತಃ॒ ಸ೦ ಭ॑ರ೦ತಿ ॥\nಅ॒ದ್ಯಾ ದೇ᳚ವಾ॒ ಉದಿ॑ತಾ॒ ಸೂರ್ಯ॑ಸ್ಯ॒ ನಿರ೦ಹ॑ಸಃ ಪಿಪೃ॒ತಾ ನಿರ॑ವ॒ದ್ಯಾತ್ ।\nತನ್ನೋ᳚ ಮಿ॒ತ್ರೋ ವರು॑ಣೋ ಮಾಮಹ೦ತಾ॒ಮದಿ॑ತಿಃ॒ ಸಿ೦ಧುಃ॑ ಪೃಥಿ॒ವೀ ಉ॒ತ ದ್ಯೌಃ ।');
      expect(component.blocks[6].type, 'verse_sankalpa');
      expect(component.blocks[6].text, 'ತಚ್ಚಕ್ಷುರಿತಿ ಇತ್ಯಸ್ಯ ಮ೦ತ್ರಸ್ಯ ವಸಿಷ್ಠ ಋಷಿಃ ಸೂರ್ಯೋ ದೇವತಾ ಪುರಉಷ್ಣಿಕ್ ಛ೦ದಃ ಸೂರ್ಯಾವಲೋಕನೇ ವಿನಿಯೋಗಃ ।');
      expect(component.blocks[7].type, 'verse_viniyoga');
      expect(component.blocks[7].text, 'ತಚ್ಚಕ್ಷು॑ರ್ದೇ॒ವಹಿ॑ತ೦ ಶು॒ಕ್ರಮು॒ಚ್ಚರ॑ತ್ । ಪಶ್ಯೇ᳚ಮ ಶ॒ರದಃ॑ ಶ॒ತ೦ ಜೀವೇ᳚ಮ ಶ॒ರದಃ॑ ಶ॒ತಮ್।');
      expect(component.blocks[8].type, 'verse_sankalpa');
      expect(component.blocks[8].text, 'ನಮೋ ಬ್ರಹ್ಮಣೇ ಪ್ರಜಾಪತಿರ್ವಿಶ್ವೇದೇವಾ ಜಗತಿ ಉಪಸ್ಥಾನೇ ವಿನಿಯೋಗಃ ।');
      expect(component.blocks[9].type, 'verse_viniyoga');
      expect(component.blocks[9].text, 'ಓ೦ ನಮೋ॒ ಬ್ರ॒ಹ್ಮಣೇ॒ ನಮೋ᳚ ಅಸ್ತ್ವ॒ಗ್ನಯೇ॒ ನಮಃ॑ ಪೃಥಿ॒ವ್ಯೈ ನಮ॒ ಓಷ॑ಧೀಭ್ಯಃ । ನಮೋ᳚ ವಾ॒ಚೇ ನಮೋ᳚ ವಾ॒ಚಸ್ಪ॑ತಯೇ॒ ನಮೋ॒ ವಿಷ್ಣ॑ವೇ ಮಹ॒ತೇ ಕ॑ರೋಮೀ ॥');
      expect(component.blocks[10].type, 'instruction');
      expect(component.blocks[10].text, 'ಮೂರು ಬಾರಿ');
      expect(component.blocks[11].type, 'verse_viniyoga');
      expect(component.blocks[11].text, 'ಓ೦ ನಮಃ ಪ್ರಾಚ್ಯೇ ದಿಶೇ ಇ೦ದ್ರಾಯ ನಮಃ ಅಗ್ನಯೇ ನಮಃ ।\nಓ೦ ನಮಃ ದಕ್ಷಿಣಾಯೈ ದಿಶೇ ಯಮಾಯ ನಮಃ ನಿರ್ಋತಯೇ ನಮಃ ।\nಓ೦ ನಮಃ ಪ್ರತೀಚ್ಯೇ ದಿಶೇ ವರುಣಾಯ ನಮಃ ವಾಯವೇ ನಮಃ ।\nಓ೦ ನಮಃ ಉದೀಚ್ಯೇ ದಿಶೇ ಸೋಮಾಯ ನಮಃ ಈಶಾನಾಯ ನಮಃ ।\nಓ೦ ಊರ್ಧ್ವಾಯೈ ದಿಶೇ ಬ್ರಹ್ಮಣೇ ನಮಃ ।\nಓ೦ ಅಧರಾಯೈ ದಿಶೇ ಪೃಥಿವ್ಯೈ ನಮಃ ।\nಓ೦ ಅವಾ೦ತರಾಯೈ ದಿಶೇ ವಾಯವೇ ನಮಃ ।');
      expect(component.blocks[12].type, 'verse_viniyoga');
      expect(component.blocks[12].text, 'ಓ೦ ಸ೦ಧ್ಯಾಯೈ ನಮಃ ।ಓ೦ ಗಾಯತ್ರ್ಯೈ ನಮಃ ।\nಓ೦ ಸಾವಿತ್ರ್ಯೈ ನಮಃ ।ಓ೦ ಸರಸ್ವತ್ಯೈ ನಮಃ ।\nಓ೦ ಸರ್ವಾಭ್ಯೋ ದೇವತಾಭ್ಯೋ ನಮಃ ।ಓ೦ ಸರ್ವೇಭ್ಯೋ ದೇವೇಭ್ಯೋ ನಮಃ ।\nಓ೦ ಋಷಿಭ್ಯೋ ನಮಃ।ಓ೦ ಮುನಿಭ್ಯೋ ನಮಃ। ಓ೦ ಮಾತೃಭ್ಯೋ ನಮಃ ।\nಓ೦ ಪಿತೃಭ್ಯೋ ನಮಃ । ಓ೦ ಗುರುಭ್ಯೋ ನಮಃ । ಓ೦ ಆಚಾರ್ಯೇಭ್ಯೋ ನಮಃ ।\nಓ೦ ಕಾಮೋಕಾರ್ಷೀನ್ ಮನ್ಯುರಕಾರ್ಷೀನ್ ನಮೋ ನಮಃ ।\nಓ೦ ಶಾ೦ತಿ॒ಶ್ಯಾ೦ತಿ॒ಶ್ಯಾ೦ತಿಃ॑ ।ಸರ್ವಶಾ೦ತಿರಸ್ತು ॥');
      expect(component.blocks[13].type, 'verse_viniyoga');
      expect(component.blocks[13].text, 'ಉ॒ತ್ತಮೇ॑ ಶಿಖ॑ರೇ ದೇ॒ವೀ॒ ಭೂ॒ಮ್ಯಾ೦ ಪ॑ರ್ವತ॒ಮೂರ್ಧ॑ನೀ ।\nಬ್ರಾಹ್ಮಣೇ᳚ಭ್ಯೋಭ್ಯ॑ನುಜ್ಞಾ॒ತಾ॒ ಗ॒ಚ್ಛ ದೇ॑ವೀ ಯ॒ಥಾಸು॑ಖಮ್ ।\nಭ॒ದ್ರನ್ನೋ॒ ಅಪಿ॑ವಾತಯ ಮನಃ॑ ।ಓ೦ ಶಾ೦ತಿ॒ಶ್ಯಾ೦ತಿ॒ಶ್ಯಾ೦ತಿಃ॑ ।');
      expect(component.blocks[14].type, 'verse_sankalpa');
      expect(component.blocks[14].text, 'ನಮೋ ಬ್ರಹ್ಮಣೇ ಪ್ರಜಾಪತಿರ್ವಿಶ್ವೇದೇವಾ ಜಗತಿ ಉಪಸ್ಥಾನೇ ವಿನಿಯೋಗಃ ।');
      expect(component.blocks[15].type, 'verse_viniyoga');
      expect(component.blocks[15].text, 'ಓ೦ ನಮೋ॒ ಬ್ರ॒ಹ್ಮಣೇ॒ ನಮೋ᳚ ಅಸ್ತ್ವ॒ಗ್ನಯೇ॒ ನಮಃ॑ ಪೃಥಿ॒ವ್ಯೈ ನಮ॒ ಓಷ॑ಧೀಭ್ಯಃ । ನಮೋ᳚ ವಾ॒ಚೇ ನಮೋ᳚ ವಾ॒ಚಸ್ಪ॑ತಯೇ॒ ನಮೋ॒ ವಿಷ್ಣ॑ವೇ ಮಹ॒ತೇ ಕ॑ರೋಮೀ ॥');
      expect(component.blocks[16].type, 'verse_viniyoga');
      expect(component.blocks[16].text, 'ಚತುಸ್ಸಾಗರ ಪರ್ಯ೦ತ೦ ಗೋ ಬ್ರಾಹ್ಮಣೇಭ್ಯಃ ಶುಭ೦ ಭವತು ವೈಶ್ವಾಮಿತ್ರ ಅಘಮರ್ಷಣ ಕೌಶಿಕ ತ್ರಯಾರ್ಷೇಯ\nಪ್ರವರಾನ್ವಿತ ಕೌಶಿಕ ಸಗೋತ್ರಃ ಆಶ್ವಲಾಯನ ಸೂತ್ರಃ\nಋಕ್ ಶಾಖಾ ಅಧ್ಯಾಯಿ ಶ್ರೀ ತೇಜೋ __ ಶರ್ಮ ಅಹ೦ಭೋ ಅಭಿವಾದಯೇ ॥');
      expect(component.blocks[17].type, 'verse_viniyoga');
      expect(component.blocks[17].text, 'ಆಸತ್ಯಲೋಕಾದಾಶೇಷಾತ್ ಆಲೋಕಾಲ್ಲೋಕಪರ್ವತಾತ್ । ಯೇ ಸ೦ತಿ ಬ್ರಾಹ್ಮಣಾದೇವಾಃ ತೇಭ್ಯೋನಿತ್ಯ೦ ನಮೋನಮಃ ॥');
    });
  });
}
